<script setup>
import {ref,onMounted,computed} from 'vue'
import {request} from './client'
defineProps({standalone:Boolean})
const info=ref(null),tab=ref('Expenses'),error=ref(''),notice=ref(''),busy=ref(false),rows=ref([]),total=ref(0),operator=ref('')
const today=new Date().toLocaleDateString('en-CA'),start=ref(today.slice(0,8)+'01'),end=ref(today)
const draft=ref({date:today,amount:'',category:'Teaching',note:'',token:crypto.randomUUID()}),config=ref({})
const tabs=computed(()=>info.value?.operator?['Expenses']:['Expenses','Operators','Content controls','Connections'])
const tabAllowed=computed(()=>!info.value?false:tab.value==='Expenses'?!!info.value.features.expenses:tab.value==='Operators'?info.value.operator_limit>0:tab.value==='Content controls'?!!info.value.features.view_limits:true)
const money=n=>new Intl.NumberFormat('en-LK',{style:'currency',currency:'LKR'}).format(n/100)
async function run(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadExpenses(){const d=await request('workspace','expenses',{start:start.value,end:end.value},'GET');rows.value=d.rows;total.value=d.total_minor}
async function load(){info.value=await request('workspace','overview',{},'GET');config.value={...info.value.settings};if(info.value.features.expenses)await loadExpenses()}
async function add(){await request('workspace','add_expense',{data:draft.value});draft.value={date:today,amount:'',category:'Teaching',note:'',token:crypto.randomUUID()};await loadExpenses();notice.value='Expense saved.'}
async function voidRow(row){const reason=window.prompt('Why should this expense be voided?');if(reason)await run(async()=>{await request('workspace','void_expense',{name:row.name,reason});await loadExpenses()})}
function csv(){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const text=[['Date','Category','Description','Amount LKR','Status','Void reason'],...rows.value.map(x=>[x.date,x.category,x.note,(x.amount_minor/100).toFixed(2),x.status,x.void_reason||''])].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['﻿'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='SISU-expenses-'+start.value+'-to-'+end.value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
onMounted(()=>run(load))
</script>
<template><section class="provider-tools" :class="{standalone}" :style="{'--provider-accent':config.accent}"><header class="page-heading"><div><span class="eyebrow">YOUR WORKSPACE, WELL ORGANISED</span><h1>{{config.display_name||'Room to run things better.'}}</h1><p>Clear expenses. A trusted team. Thoughtful content controls.</p></div><a v-if="standalone" href="/api/method/logout" class="button subtle">Sign out</a><span v-if="info" class="badge violet">{{info.plan}} · {{info.operator?'Operator':'Provider'}}</span></header>
<p v-if="error" role="alert" class="tools-alert">{{error}}</p><p v-if="notice" role="status" class="tools-success">{{notice}}</p><p v-if="busy" role="status">Saving or loading…</p>
<template v-if="info"><nav class="tabs" aria-label="Provider tools"><button v-for="name in tabs" :key="name" :class="{selected:tab===name}" @click="tab=name">{{name}}</button></nav>
<div v-if="!tabAllowed" class="panel"><h2>This tool is not included in your plan.</h2><p>Your current plan does not include {{tab.toLowerCase()}}. Compare the available plans, or open Connections to check service setup.</p><a href="#subscription" class="button primary">Compare packages</a></div>
<template v-else-if="tab==='Expenses'"><div class="tools-stats"><article><small>EXPENSES IN THIS PERIOD</small><strong>{{money(total)}}</strong><span>Voided entries excluded</span></article><article><small>RECORDED ENTRIES</small><strong>{{rows.length}}</strong><span>Auditable entries, with reasons for changes</span></article></div><div class="tools-columns"><form class="panel" @submit.prevent="run(add)"><h2>Record an expense</h2><label>Date<input type="date" v-model="draft.date" :max="today" required></label><div class="form-row"><label>Amount · LKR<input type="number" min="0.01" max="100000000" step="0.01" v-model="draft.amount" required></label><label>Category<select v-model="draft.category"><option v-for="c in ['Teaching','Rent','Utilities','Marketing','Materials','Transport','Other']">{{c}}</option></select></label></div><label>Description<textarea v-model="draft.note" minlength="3" maxlength="500" required placeholder="What was this expense for?"/></label><button class="button primary" :disabled="busy">Save expense</button><p class="field-help">Recording an expense does not send a payment or reduce your payout balance.</p></form><section class="panel"><h2>Expense register</h2><form class="form-row" @submit.prevent="run(loadExpenses)"><label>From<input type="date" v-model="start" required></label><label>To<input type="date" v-model="end" :min="start" required></label><button class="button subtle" :disabled="busy">Apply dates</button></form><button class="text-button" :disabled="!rows.length" @click="csv">Download CSV</button><div class="table-wrap"><table><thead><tr><th>Expense</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.name"><td><strong>{{row.category}}</strong><small>{{row.date}} · {{row.note}}</small><small v-if="row.void_reason">Reason: {{row.void_reason}}</small></td><td>{{money(row.amount_minor)}}</td><td>{{row.status}}</td><td><button v-if="row.status==='Active'" class="text-button" :disabled="busy" @click="voidRow(row)">Void</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty-mini">No expenses in this date range.</p></section></div></template>
<section v-else-if="tab==='Operators'" class="panel"><h2>A helping hand, with clear boundaries.</h2><p>{{info.operator_limit}} operator seats included. Operators can record expenses and void their own entries. They cannot approve class payments, access student records or request payouts.</p><form class="form-row" @submit.prevent="run(async()=>{await request('workspace','add_operator',{user:operator});operator='';await load();notice='Operator access saved.'})"><label>Existing operator account email<input v-model="operator" type="email" required placeholder="operator@example.com"></label><button class="button primary" :disabled="busy">Grant access</button></form><p class="field-help">Create the staff account through your site administrator first. An existing student or teacher account cannot be reassigned here.</p><article v-for="person in info.operators" :key="person.name" class="tools-person"><div><strong>{{person.subject_user}}</strong><small>Expense entry · {{person.status}}</small></div><button v-if="person.status==='Active'" class="button subtle small" :disabled="busy" @click="run(async()=>{await request('workspace','revoke_operator',{name:person.name});await load()})">Revoke access</button></article></section>
<form v-else-if="tab==='Content controls'" class="panel" @submit.prevent="run(async()=>{config=await request('workspace','save_settings',{data:config});notice='Content settings saved.'})"><h2>A thoughtful boundary around your content.</h2><p>Limits apply to protected SISU documents and recordings. Third-party video hosting still controls its own player and sharing options.</p><div class="tools-fields"><label>Document opens per student<input type="number" min="0" max="1000" step="1" v-model.number="config.document_views"><small>Views and downloads share this lifetime counter. 0 = unlimited.</small></label><label>Protected video plays per student<input type="number" min="0" max="1000" step="1" v-model.number="config.video_views"><small>0 = unlimited. A new authorised playback counts as one play.</small></label><label>Concurrent browser sessions<input type="number" min="0" max="10" step="1" v-model.number="config.concurrent_sessions"><small>0 = unlimited. An inactive session releases after 15 minutes.</small></label></div><template v-if="info.features.watermark"><label class="tools-check"><input type="checkbox" v-model="config.pdf_watermark">Add student ID and delivery date to downloaded and viewed PDFs</label><p class="field-help">The original file stays unchanged. PDF watermarks discourage sharing; they do not prevent copying.</p><h3>Your workspace identity</h3><label class="tools-check"><input type="checkbox" v-model="config.white_label">Use this name and accent as the institute campus brand</label><div class="form-row"><label>Workspace display name<input v-model="config.display_name" maxlength="80" placeholder="Your academy"></label><label>Accent colour<input type="color" v-model="config.accent"></label></div><p class="field-help">These settings brand your provider tools. For an institute, enabling the campus brand also replaces the sidebar wordmark and campus name after reload. Website, email, mobile-app and domain branding require deployment configuration.</p></template><button class="button primary" :disabled="busy">Save content settings</button></form>
<section v-else-if="tab==='Connections'" class="panel"><h2>Connected teaching, clearly configured.</h2><div class="tools-connections"><article><h3>Private video storage</h3><span class="badge">{{info.readiness.private_video?'Credentials present':'Setup required'}}</span><p>Private bucket, upload reservations and short-lived playback links. Configure storage, versioning and browser access before use.</p></article><article><h3>YouTube, Vimeo & live lessons</h3><p>Schedule lessons in My schedule. YouTube broadcasts play inside SISU. Vimeo recordings use the host’s privacy settings. Protected Zoom meetings can be created after the session is saved and that provider’s Zoom credentials are configured. Meet and YouTube broadcast links remain teacher-managed.</p></article><article><h3>WhatsApp & reminders</h3><p>Connect approved business credentials and templates. Sending requires consent and successful provider setup.</p></article><article><h3>Your own domain & mobile app</h3><p>Domain setup needs DNS and HTTPS. Native store publishing and full white labelling are deployment work, not activated by selecting a package.</p></article></div></section>
</template></section></template>
<style scoped>
.provider-tools .button.primary{background:var(--provider-accent,#51258a)}.provider-tools{max-width:1400px;margin:auto}.provider-tools.standalone{padding:40px;font-family:Manrope,system-ui,sans-serif}.tools-alert{background:#fff0f0;color:#9e2834;padding:15px;border-radius:12px}.tools-success{background:#edf8f0;padding:15px;border-radius:12px;color:#296c46}.tabs{margin-bottom:24px;flex-wrap:wrap}.panel{padding:25px;border:1px solid #e5ddf0;border-radius:20px;background:var(--surface,#fff);margin-bottom:20px}.panel h2{font-size:21px;margin:0 0 12px}.panel p{line-height:1.7;color:var(--muted,#786c87)}.tools-stats{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px}.tools-stats article{background:linear-gradient(135deg,#f1eafa,#fbf9fe);border:1px solid #e2d6f0;border-radius:20px;padding:24px;display:grid;gap:10px;color:#46236e}.tools-stats strong{font-size:32px}.tools-stats small{font-size:10px;letter-spacing:1.5px}.tools-stats span{font-size:12px}.tools-columns{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.4fr);gap:20px}.tools-columns form.panel{align-self:start}.provider-tools label{display:grid;gap:9px;font-size:13px;margin-bottom:17px}.provider-tools input,.provider-tools select,.provider-tools textarea{padding:12px;border:1px solid #dfd5ec;border-radius:10px;max-width:100%;font:inherit;background:var(--surface,#fff);color:inherit}.provider-tools textarea{min-height:90px}.tools-fields{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.tools-fields small{font-size:11px;line-height:1.6;color:#796e86}.tools-person{display:flex;justify-content:space-between;align-items:center;padding:18px 0;border-top:1px solid #ece5f3}.tools-person small,td small{display:block;font-size:11px;margin-top:6px;color:#796e86}.tools-check{display:flex!important;align-items:center}.tools-check input{width:18px;height:18px}.tools-connections{display:grid;grid-template-columns:1fr 1fr;gap:24px}.tools-connections article{border-top:1px solid #e9e1f0;padding-top:16px}.table-wrap{overflow:auto}table{width:100%;font-size:12px;border-collapse:collapse}td,th{padding:15px 8px;text-align:left;border-bottom:1px solid #eee7f4}input[type=color]{width:90px;height:45px}@media(max-width:900px){.tools-columns,.tools-fields{grid-template-columns:1fr}}@media(max-width:600px){.tools-stats,.tools-connections{grid-template-columns:1fr}.provider-tools.standalone{padding:20px}}
</style>
